CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email_hash text NOT NULL UNIQUE, email_enc text NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'patient' CHECK(role IN ('patient','clinic','admin')), clinic_id uuid, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles (user_id uuid PRIMARY KEY REFERENCES users(id), payload_enc text NOT NULL);
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), payload_enc text NOT NULL, raw_enc text, mime text NOT NULL, state text NOT NULL DEFAULT 'uploaded' CHECK(state IN ('uploaded','processing','ready','needs_review','failed')), processing_stage text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, locked_at timestamptz, error_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reports_patient_date ON reports(user_id,created_at DESC);
CREATE TABLE report_values (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE,payload_enc text NOT NULL);
CREATE INDEX values_report ON report_values(report_id);
CREATE TABLE reference_ranges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),test_code text NOT NULL,label text NOT NULL,unit text NOT NULL,low double precision NOT NULL,high double precision NOT NULL,borderline_low double precision,borderline_high double precision,critical_low double precision,critical_high double precision,age_min integer NOT NULL DEFAULT 18,age_max integer NOT NULL DEFAULT 120,sex text NOT NULL DEFAULT 'any' CHECK(sex IN ('any','female','male')),source_url text NOT NULL,source_label text NOT NULL,verification text NOT NULL DEFAULT 'draft' CHECK(verification IN ('draft','synthetic_only','verified')),version integer NOT NULL DEFAULT 1,CHECK(low<=high),CHECK(age_min<=age_max),CHECK(borderline_low IS NULL OR borderline_low<=low),CHECK(borderline_high IS NULL OR borderline_high>=high),CHECK(critical_low IS NULL OR critical_low<COALESCE(borderline_low,low)),CHECK(critical_high IS NULL OR critical_high>COALESCE(borderline_high,high)),UNIQUE(test_code,unit,sex,age_min,age_max,version));
CREATE TABLE explanations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE,locale text NOT NULL CHECK(locale IN ('en','ur')),payload_enc text NOT NULL,UNIQUE(report_id,locale));
CREATE TABLE medications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),payload_enc text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reminders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),medication_id uuid REFERENCES medications(id) ON DELETE SET NULL,payload_enc text NOT NULL,due_at timestamptz NOT NULL,interval_minutes integer CHECK(interval_minutes>=60 AND interval_minutes<=525600),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reminders_due ON reminders(due_at) WHERE active;
CREATE TABLE follow_ups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),payload_enc text NOT NULL,due_at timestamptz NOT NULL,completed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE escalations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL UNIQUE REFERENCES reports(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id),clinic_id uuid NOT NULL,severity text NOT NULL CHECK(severity IN ('review','concerning','critical')),state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','in_review','closed')),note_enc text,reviewer_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX escalations_clinic ON escalations(clinic_id,state,created_at DESC);
CREATE TABLE chat_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL CHECK(role IN ('user','assistant')),content_enc text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid,patient_id uuid,action text NOT NULL,resource_id text,outcome text NOT NULL CHECK(outcome IN ('allowed','denied','error')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_patient_time ON audit_logs(patient_id,created_at DESC);
CREATE FUNCTION immutable_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit logs are append-only'; END; $$;
CREATE TRIGGER audit_no_mutation BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE TABLE knowledge_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),test_code text NOT NULL,locale text NOT NULL CHECK(locale IN ('en','ur')),content text NOT NULL,source text NOT NULL,reviewed boolean NOT NULL DEFAULT false,embedding vector(384) NOT NULL);
CREATE INDEX knowledge_vector ON knowledge_chunks USING hnsw (embedding vector_cosine_ops);
CREATE TABLE refresh_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),family_id uuid NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,used_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX refresh_family ON refresh_tokens(family_id);
CREATE TABLE automation_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL,idempotency_key text NOT NULL UNIQUE,payload_enc text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_patient ON automation_events(user_id,created_at DESC);
CREATE TABLE webhook_nonces (nonce text PRIMARY KEY,expires_at timestamptz NOT NULL);
